package dev.slithergoh.pixelmonradar.client;

import com.mojang.blaze3d.vertex.*;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.core.BlockPos;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.Vec3;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderLevelStageEvent;
@EventBusSubscriber(modid="pixelmonradar",value=Dist.CLIENT)public final class OreWorldRenderer{@SubscribeEvent public static void render(RenderLevelStageEvent e){if(!RadarSettings.oreEspEnabled||e.getStage()!=RenderLevelStageEvent.Stage.AFTER_CUTOUT_MIPPED_BLOCKS_BLOCKS)return;Minecraft mc=Minecraft.getInstance();if(mc.level==null||mc.player==null)return;Vec3 cam=mc.gameRenderer.getMainCamera().getPosition();PoseStack ps=e.getPoseStack();ps.pushPose();ps.translate(-cam.x,-cam.y,-cam.z);MultiBufferSource.BufferSource bs=mc.renderBuffers().bufferSource();VertexConsumer vc=bs.getBuffer(RenderType.lines());int count=0;for(BlockPos p:OreScanner.scan()){if(count++>=1200)break;ResourceLocation id=BuiltInRegistries.BLOCK.getKey(mc.level.getBlockState(p).getBlock());float[]c=color(id);double d=Math.sqrt(p.distSqr(mc.player.blockPosition()));float a=(float)Math.max(.45,1.0-d/Math.max(16,RadarSettings.oreRange)*.35);double pad=d<12?.035:.012;LevelRenderer.renderLineBox(ps,vc,p.getX()-pad,p.getY()-pad,p.getZ()-pad,p.getX()+1+pad,p.getY()+1+pad,p.getZ()+1+pad,c[0],c[1],c[2],a,c[0],c[1],c[2]);}bs.endBatch(RenderType.lines());ps.popPose();}
 private static float[]color(ResourceLocation id){String p=id.getPath();if(p.contains("diamond")||p.contains("crystal"))return new float[]{.2f,1f,1f};if(p.contains("emerald"))return new float[]{.2f,1f,.35f};if(p.contains("redstone")||p.contains("ruby"))return new float[]{1f,.15f,.15f};if(p.contains("lapis")||p.contains("sapphire"))return new float[]{.2f,.4f,1f};if(p.contains("gold"))return new float[]{1f,.8f,.1f};if(p.contains("iron")||p.contains("silver")||p.contains("platinum"))return new float[]{.9f,.9f,.9f};if(p.contains("copper")||p.contains("bauxite"))return new float[]{1f,.45f,.18f};if(p.contains("coal"))return new float[]{.55f,.55f,.55f};return new float[]{1f,.3f,.8f};}}
